import React, { type ComponentType } from "react"
import { Accordion, Typography, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Box } from "@/components/frames/Box"

/** One collapsible section of a {@link LabeledAccordionCard}. */
export interface LabeledAccordionCardItem {
    /** Stable id — also the expand key (matched against `defaultExpandedKeys`). */
    id: string
    /** Trigger headline (the always-visible row). */
    title: string
    /** Optional muted second line in the trigger (a count / hint), under the title. */
    subtitle?: string
    /**
     * Optional trailing slot in the trigger row, right of the title and LEFT of the
     * caret — a status chip / score / count that belongs to the collapsed header
     * (e.g. a per-requirement score, a milestone `StatusChip`, a read count). The
     * title truncates to make room; this stays at intrinsic width.
     */
    titleEnd?: ComponentType
    /** Panel content, revealed when the item expands — a buildable slot. */
    body: ComponentType
}

/** Props for the {@link LabeledAccordionCard} block. */
export interface LabeledAccordionCardProps extends WithClassNames<undefined> {
    /**
     * Section label rendered OUTSIDE (above) the card — forwarded to {@link LabeledCard}.
     * OMIT it when the card sits in a pane that already carries a heading/tab of its
     * own (e.g. the Playground Lab "Resources" tab): a second label there is
     * label-on-label (accordion.md §3d). With no label the card renders bare
     * (just the {@link SurfaceListCard} frame), no section wrapper.
     */
    label?: string
    /** Optional passive right-aligned tag in the label row (count / unit). Ignored without `label`. */
    labelEnd?: string
    /** Optional right-aligned action slot in the label row (a button) — a buildable slot. Ignored without `label`. */
    action?: ComponentType
    /** The collapsible sections, in order. */
    items: ReadonlyArray<LabeledAccordionCardItem>
    /**
     * Allow more than one section open at once. Default `false` (a single-open
     * accordion). `allowsMultipleExpanded`, NOT `selectionMode` — that prop does
     * not exist on HeroUI's Accordion (accordion.md §3d).
     */
    allowsMultipleExpanded?: boolean
    /**
     * Sections expanded on mount, keyed by item `id`. A `Set`, not an array
     * (react-aria's collection key set — accordion.md §3d).
     */
    defaultExpandedKeys?: Set<string>
    /**
     * When this card sits NESTED inside another surface (a modal/drawer body),
     * pass `bordered` so it delineates with a border instead of a shadow that can
     * render invisible in dark mode (card.md §0). Forwarded to {@link SurfaceListCard}.
     */
    bordered?: boolean
}

/**
 * The collapsible frame — one bounded `bg-surface` card of sections whose separators
 * run FULL-BLEED to the card edge. Shared by the labeled and unlabeled forms.
 */
const AccordionFrame = ({
    items,
    allowsMultipleExpanded,
    defaultExpandedKeys,
    bordered,
}: Pick<
    LabeledAccordionCardProps,
    "items" | "allowsMultipleExpanded" | "defaultExpandedKeys" | "bordered"
>) => (
    <SurfaceListCard bordered={bordered}>
        {/* variant="default" (NOT surface): the base variant keeps the item separator
            FULL-BLEED (`left-0 w-full`); surface would inset it to 3%. The bg-surface
            frame + clipped corners come from SurfaceListCard, so the accordion stays
            transparent and rides on it (accordion.md §3e).

            Local `--separator` override: the base variant's separator token reads a bit
            heavy; re-point it to the SAME light hairline the SurfaceListCard rows use
            (`bg-surface-foreground/6`) so this card's dividers match the surface-list
            family. Overriding the token (which the item `::after` reads via `bg-separator`)
            is escape-free — no fighting HeroUI's unlayered `::after` with `!important`. */}
        <Accordion
            variant="default"
            style={{ "--separator": "color-mix(in oklab, var(--surface-foreground) 6%, transparent)" } as React.CSSProperties}
            allowsMultipleExpanded={allowsMultipleExpanded}
            defaultExpandedKeys={defaultExpandedKeys}
        >
            {items.map((item) => {
                const TitleEnd = item.titleEnd
                const Body = item.body
                return (
                    <Accordion.Item
                        key={item.id}
                        id={item.id}
                        aria-label={item.title}
                    >
                        <Accordion.Heading>
                            <Accordion.Trigger>
                                <div className="flex min-w-0 flex-1 flex-col gap-0 text-left">
                                    <Typography type="body-sm" weight="medium" truncate>
                                        {item.title}
                                    </Typography>
                                    {item.subtitle != null ? (
                                        <Typography type="body-xs" color="muted" truncate>
                                            {item.subtitle}
                                        </Typography>
                                    ) : null}
                                </div>
                                {/* titleEnd + caret share one group so the trailing chip/count keeps
                                    a `gap-3` breathing room from the indicator instead of touching it */}
                                <div className="flex shrink-0 items-center gap-3">
                                    {TitleEnd ? <TitleEnd /> : null}
                                    <Accordion.Indicator />
                                </div>
                            </Accordion.Trigger>
                        </Accordion.Heading>
                        <Accordion.Panel>
                            <Accordion.Body className={cn("pt-0")}>
                                <Body />
                            </Accordion.Body>
                        </Accordion.Panel>
                    </Accordion.Item>
                )
            })}
        </Accordion>
    </SurfaceListCard>
)

/**
 * A "Accordion Card": one bounded `bg-surface` frame holding collapsible sections
 * whose separators run FULL-BLEED to the card edge — the same skin as
 * {@link SurfaceListCard}, but each row expands. Pass {@link LabeledAccordionCardProps.label}
 * to add a section label OUTSIDE the card; omit it in a pane that already has a tab/heading.
 *
 * The full-bleed separator is why this uses `Accordion variant="default"` rather than
 * the usual `surface` skin: HeroUI's `.accordion--surface` insets the item separator to
 * `left-[3%] w-[94%]`, while the BASE variant keeps it `left-0 w-full`. The surface look
 * (bg + radius + clipped corners) is supplied by the wrapping {@link SurfaceListCard}, so
 * the accordion can stay transparent and ride on it (accordion.md §3d / §3e, card.md §3).
 *
 * Use when a "list card" needs its rows to collapse/expand by group (e.g. the Playground
 * Lab "Resources" tab grouped by kind) — never hand-roll a `<button>` + caret, which
 * reimplements the keyboard/aria HeroUI already ships. Each item's trigger is `title`
 * (+ optional `subtitle` line, + optional trailing `titleEnd` chip); the panel `body` is
 * free content.
 *
 * @param props - {@link LabeledAccordionCardProps}
 * @see Story: .storybook/stories/blocks/cards/LabeledAccordionCard/LabeledAccordionCard.stories
 */
export const LabeledAccordionCard = ({
    label,
    labelEnd,
    action,
    items,
    allowsMultipleExpanded = false,
    defaultExpandedKeys,
    bordered = false,
    className,
}: LabeledAccordionCardProps) => {
    const frame = (
        <AccordionFrame
            items={items}
            allowsMultipleExpanded={allowsMultipleExpanded}
            defaultExpandedKeys={defaultExpandedKeys}
            bordered={bordered}
        />
    )
    // no label → the pane already carries a heading/tab; render the frame bare
    if (label == null) {
        return (
            <Box identity={{ tier: "block", component: "LabeledAccordionCard" }} className={cn(className)}>
                {frame}
            </Box>
        )
    }
    return (
        <LabeledCard
            identity={{ tier: "block", component: "LabeledAccordionCard" }}
            label={label}
            labelEnd={labelEnd}
            action={action}
            frameless
            className={className}
        >
            {frame}
        </LabeledCard>
    )
}

import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { Card, CardContent, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { SeeMoreLink } from "@/components/blocks/navigation/SeeMoreLink"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Props for the {@link LabeledCard} block. */
export interface LabeledCardProps extends WithClassNames<undefined> {
    /** Section title rendered OUTSIDE (above) the card. */
    label: string
    /**
     * Optional secondary label pinned to the RIGHT of the label row (muted) — a
     * passive tag, NOT an action (e.g. a currency "VND", a count, a unit). Rendered
     * only when neither `action` nor `onSeeMore` claim the right slot.
     */
    labelEnd?: string
    /**
     * When provided, renders a shared {@link SeeMoreLink} on the right of the
     * label (semibold accent text + a caret that slides right on hover).
     */
    onSeeMore?: () => void
    /** Text for the see-more link. Defaults to "See more" — pass `t(...)` to localise. */
    seeMoreLabel?: string
    /**
     * Arbitrary right-aligned slot in the label row (e.g. an owner "Add / manage"
     * button) — a buildable slot. Takes precedence over `onSeeMore` when both are passed.
     */
    action?: ComponentType
    /** Card body content. */
    children: ReactNode
    /**
     * Optional secondary slot rendered OUTSIDE (below) the card, `gap-2` from
     * it — a caption/prompt/status that belongs to the section but not inside the
     * surface (e.g. a "complete all 3 to claim" prompt, a claim button) — a
     * buildable slot. Kept below the card so it never becomes surface-in-surface.
     * Caller owns its alignment.
     */
    description?: ComponentType
    /** Extra classes merged onto the card content wrapper. */
    contentClassName?: string
    /**
     * When true, drop the inner `<Card>` frame and render children directly under
     * the label — for sections whose content is ITSELF card(s) (e.g. a grid of
     * resume / course cards), so they never nest card-in-card.
     */
    frameless?: boolean
    /**
     * When true, the framed card drops padding on BOTH the root `.card` (HeroUI
     * bakes `p-4` there) and `CardContent`, so an EDGE-OWNING child (Accordion /
     * Table / full-bleed divider list) sits flush to the card edges — avoids the
     * inset-divider look. Ignored when `frameless`.
     */
    flushContent?: boolean
    /**
     * When true, the section + framed card stretch to fill their container's height
     * (`h-full` + the card grows via `flex-1`). Use for side-by-side cards in a grid
     * row so uneven content (e.g. a 1-line vs 2-line empty state) still renders at
     * equal height. Ignored when `frameless`.
     */
    fillHeight?: boolean
    /**
     * Renders the label as a SUBTLE eyebrow (`text-xs text-muted`) with a tighter
     * `gap-2` to the content, instead of the default section `Label` + `gap-3`. For
     * a minor/secondary header over a block — e.g. a time-bucket "Today" over a run
     * list — where a full section label reads too heavy (teacher 2026-07-13: "if a card
     * needs a secondary label, use label-gap-2"). `labelEnd` shrinks to `text-xs` to match.
     */
    subtleLabel?: boolean
    /**
     * When true, adds `border border-default` on top of the default
     * `shadow-surface` — for shells that need to stand out as a distinct
     * bounded surface even against a `bg-surface` sibling (e.g. FlipCard's
     * question/answer pair). Default false preserves the elevation-only
     * convention for every other LabeledCard consumer.
     */
    bordered?: boolean
    /**
     * Caller identity to wear on this block's root `<section>` instead of its own — pass this
     * when a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its
     * own) is using this card AS its root element, instead of wrapping it in a raw `<div
     * data-tier=… data-component=…>`. See `_identity.ts`. Omitted → this section keeps emitting
     * no `data-tier`/`data-component` at all, unchanged (this block has no identity of its own).
     */
    identity?: CallerIdentity
}

/**
 * The StarCi section card (UI 2.0): the title is a `Label` that sits OUTSIDE,
 * above the card, while the `Card` holds only content — `<Label/>` then
 * `<Card>…</Card>`. Optionally shows a right-aligned "see more →" link (the caret
 * slides right on hover). Replaces the legacy in-card header (SectionCard); owns
 * the whole look so features just pass label / see-more / children.
 *
 * @param props - {@link LabeledCardProps}
 * @see Story: .storybook/stories/blocks/cards/LabeledCard/LabeledCard.stories
 */
export const LabeledCard = ({
    label,
    labelEnd,
    onSeeMore,
    seeMoreLabel = "See more",
    action: Action,
    children,
    description: Description,
    className,
    contentClassName,
    frameless = false,
    flushContent = false,
    fillHeight = false,
    subtleLabel = false,
    bordered = false,
    identity,
}: LabeledCardProps) => {
    // Right slot of the label row — action wins over onSeeMore, which wins over labelEnd.
    const endSlot = Action ? <Action /> : (onSeeMore ? (
        <SeeMoreLink onPress={onSeeMore} size={subtleLabel ? "xs" : "sm"}>
            {seeMoreLabel}
        </SeeMoreLink>
    ) : labelEnd != null ? (
        <Typography size={subtleLabel ? "xs" : "sm"} color="muted" classNames={["shrink-0"]} text={labelEnd} />
    ) : null)
    // Non-subtle label goes through the atom instead of HeroUI `Label`: `Label` renders
    // exactly 14px/500/lh-20 = `size="sm" weight="medium"` (documented equivalence, see
    // `composites/cards/SurfaceCard/surface-card-header.tsx`), so the shape is unchanged.
    const labelSlot = subtleLabel ? (
        <Typography size="xs" color="muted" truncate classNames={["min-w-0"]} text={label} />
    ) : (
        <Typography size="sm" weight="medium" classNames={["min-w-0"]} text={label} />
    )
    // card body: frameless = content is itself card(s) → no inner Card (avoid nesting)
    const body = frameless ? (
        <Box className={contentClassName}>{children}</Box>
    ) : (
        <Card
            className={cn(
                bordered && "border border-default",
                fillHeight && "flex-1",
                // root `.card` bakes p-4 — zero it here or flush children stay inset
                flushContent && "gap-0 overflow-hidden p-0",
            )}
        >
            <CardContent className={cn(flushContent && "p-0", fillHeight && "h-full", contentClassName)}>
                {children}
            </CardContent>
        </Card>
    )
    return (
        <section
            {...resolveIdentity(identity, { tier: "composite", name: "LabeledCard" })}
            data-principle={subtleLabel ? "sublabel-field" : "label-field"}
            className={cn("flex flex-col", subtleLabel ? "gap-2" : "gap-3", fillHeight && "h-full", className)}
        >
            <StackH gap={4} principle="content-row" justify="between" items={[() => labelSlot, () => endSlot]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            />
            {/* description sits OUTSIDE (below) the card, gap-2 — never surface-in-surface */}
            {Description ? (
                <StackV gap={3} items={[() => body, () => <Description />]} />
            ) : body}
        </section>
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/**
 * Props for the {@link PressableCard} block.
 *
 * TIER NOTE: this folder sits under `blocks/cards`, but the component itself
 * owns no domain entity — every prop here is a shape (`children`, `onPress`,
 * `href`, `actions`) never a field of something fetched. That is BLOCK-7's
 * detection signal: it is really a **composite** mis-filed in a block folder.
 * Left in place (moving the folder breaks every importer below), but treated
 * as a composite for this pass — one file, `cn()` allowed (COMPOSITE-5), and
 * `className` kept as a raw string rather than `classNames: Array<AllowedClassName>`
 * because three real callers outside this folder (`GroupPressableCard`,
 * `SummaryCard`, `ConsultantCard`) already forward arbitrary skin classes
 * (radius/border/hover overrides) through it — narrowing the type here would
 * break them without touching a single one of their files.
 *
 * `composites/cards/SurfaceCard` (`SurfaceCard`, exported off `Base`) is the
 * emerging canonical member for this exact job — same whole-card press target,
 * same stretched-link `actions` pattern, plus ripple/selection/verdict-band —
 * and its own header explicitly notes it folds in "was `PressableCard`". It is
 * NOT swapped in here: its hover/ripple treatment differs from this file's
 * (tint-on-hover, no ripple), so delegating to it would change the rendered
 * look for the three live callers above, not just the code shape. Consolidating
 * onto `SurfaceCard` is a separate migration (each caller needs the `children`
 * → `body` slot conversion too), left as debt rather than folded in silently.
 */
export interface PressableCardProps extends WithClassNames<undefined> {
    /** Card body — composed freely by the caller (icon tiles, text, chips…). */
    children: React.ReactNode
    /**
     * Press handler for an action card (select / toggle). Ignored when
     * {@link PressableCardProps.href} is set. One of `onPress` / `href` should
     * be provided for the card to be interactive.
     */
    onPress?: () => void
    /** Navigation target — renders the card as an anchor when provided. */
    href?: string
    /** Disables interaction and dims the card (action cards only). */
    isDisabled?: boolean
    /**
     * Secondary interactive controls (buttons / menus) that live INSIDE the card
     * but act INDEPENDENTLY of the whole-card press — e.g. a "Continue" button +
     * an overflow menu on a course-progress card.
     *
     * Providing this switches the card to the accessible **stretched-link**
     * pattern (Inclusive Components / Adrian Roselli): the whole-card target
     * becomes a TRANSPARENT overlay that covers the card, and these actions sit
     * ABOVE it (later in source order + `z-10`) so each stays separately
     * clickable. This is the correct alternative to illegally nesting a
     * `<button>` inside the card's own `<button>`/`<a>` — which is invalid HTML,
     * breaks the keyboard/AT focus order, AND is what made the card grow tall
     * (a block button laying its interactive children out on their own lines).
     *
     * REQUIRES {@link PressableCardProps.label} — the overlay target no longer
     * wraps the children text, so it needs its own accessible name.
     */
    actions?: ComponentType
    /**
     * Accessible name for the whole-card press target. REQUIRED when
     * {@link PressableCardProps.actions} is set (the stretched overlay covers the
     * card but has no visible text of its own, so it must carry an `aria-label`).
     * Optional otherwise — without `actions` the children ARE the card's
     * accessible name, so pass this only when they carry no readable text (an
     * icon-only tile). Keep it descriptive of the destination/action ("Open the
     * Fullstack Mastery track"), never generic ("click here").
     */
    label?: string
    /**
     * Caller identity to wear on this card's root instead of its own — pass this
     * when a sentence-tier component roots on this card (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * A whole-card press target with the default surface card look (surface fill,
 * concentric `rounded-3xl`, fixed `px-4 py-3` padding, `shadow-surface`
 * elevation AT REST — per `card.md` §0, a top-level bounded card, so it must
 * read as a card even before hover) plus a hover affordance and keyboard
 * focus ring. Exists because HeroUI v3 `Card` is a
 * non-interactive `<div>` — this component owns the card styling on a real
 * `<button>` / `<a>` so features can compose a clickable card without
 * hand-rolling styles (per the no-style-in-features rule). Use for navigation
 * tiles, selectable option cards, and bookmark rows.
 *
 * When the card also needs its OWN buttons (a "Continue" CTA, an overflow menu),
 * pass them via {@link PressableCardProps.actions} + {@link PressableCardProps.label}:
 * the card renders as the accessible stretched-link pattern (a transparent
 * whole-card overlay UNDER the actions) instead of nesting interactive elements
 * — see the `actions` prop docs.
 *
 * @param props - {@link PressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/PressableCard/PressableCard.stories
 */
export const PressableCard = ({
    children,
    onPress,
    href,
    isDisabled = false,
    actions: Actions,
    label,
    className,
    identity,
}: PressableCardProps) => {
    // Shared card surface + disabled dim, identical across both render paths so
    // a card reads the same with or without actions. `shadow-surface` is a
    // top-level bounded card (card.md §0 elevation convention) — it must read as
    // one at rest, not only once the pointer arrives (teacher: "render it as a card").
    // One hover treatment only (tint) — no lift variant, no press-scale.
    const surface = cn(
        "rounded-3xl bg-surface px-4 py-3 text-left shadow-surface transition-colors hover:bg-surface-secondary",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "PressableCard" })

    // ── Simple whole-card target (no secondary actions) — the common case;
    // the whole card is ONE <button>/<a> and its children are its label. ──────
    if (!Actions) {
        const base = cn(
            "block w-full outline-none focus-visible:ring-2 focus-visible:ring-accent",
            surface,
        )
        if (href && !isDisabled) {
            return (
                <a href={href} aria-label={label} className={base} {...identityAttrs}>
                    {children}
                </a>
            )
        }
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                aria-label={label}
                className={cn(base, !isDisabled && "cursor-pointer")}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }

    // ── Card WITH its own buttons — stretched-link pattern. The card is a plain
    // relative <div>; a transparent overlay <a>/<button> covers it (whole-card
    // press), and the actions sit ABOVE the overlay so they stay clickable. No
    // interactive element is ever nested inside another. Row built with `StackH`
    // (frame tier) instead of a hand-rolled `flex items-center gap-3` wrapper —
    // same shape as `composites/cards/SurfaceCard`'s own actions branch. ───────
    const overlay = cn(
        // covers the whole card; the focus ring reads as a card-level ring since
        // the overlay's border-box IS the card's bounds
        "absolute inset-0 rounded-3xl outline-none focus-visible:ring-2 focus-visible:ring-accent",
        isDisabled ? "cursor-not-allowed" : "cursor-pointer",
    )
    return (
        <div className={cn("relative w-full", surface)} {...identityAttrs}>
            <StackH
                gap={4}
                items={[
                    () => <div className="min-w-0 flex-1">{children}</div>,
                    () => (
                        <div className="relative z-10">
                            <StackH gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." classNames={["shrink-0"]} items={[() => <Actions />]} />
                        </div>
                    ),
                ]}
            />
            {href && !isDisabled ? (
                <a href={href} aria-label={label} className={overlay} />
            ) : (
                <button
                    type="button"
                    onClick={onPress}
                    disabled={isDisabled}
                    aria-label={label}
                    className={overlay}
                />
            )}
        </div>
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import {
    CaretRightIcon as ChevronRightIcon,
} from "@phosphor-icons/react"
import {
    PressableCard,
} from "../PressableCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/**
 * Props for {@link SummaryCard}. Every field is an already-resolved shape
 * (icon, value, label, hint) — this card takes no domain entity, which is
 * why it lives at the composite tier despite sitting in `blocks/cards`
 * (BLOCK-7): the folder names a tier the component never earned.
 */
export interface SummaryCardProps {
    /** Leading icon for the metric — a buildable slot, not a built element. */
    icon: ComponentType
    /** Headline value (e.g. a count). */
    value: string
    /** Short label under the value. */
    label: string
    /** Optional one-line hint under the label. */
    hint?: string
    /** Called when the card is activated (e.g. jump to a tab). */
    onPress?: () => void
    /**
     * Where this sits inside its parent. Appearance is not passable — it is
     * already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "SummaryCard" } as const

/**
 * A compact pressable metric card (icon + big value + label, with a trailing
 * chevron) used in the profile overview to surface a deeper tab. Built on
 * {@link PressableCard} for the spring/hover feel; layers its own outlined
 * "default" card look on top of that surface. Presentational — the caller
 * wires `onPress`.
 *
 * `PressableCard` has not itself been ported to the closed `classNames`
 * vocabulary, so its `className` string prop is composed here with `cn`
 * (COMPOSITE-5 — appearance is this tier's job); `SummaryCard` renders no
 * `<div>` of its own beyond what `PressableCard`'s button/anchor already
 * emits, so it carries no separate `data-tier`/`data-component` badge —
 * `PressableCard` offers no slot for one, and wrapping it in an extra `<div>`
 * just to hang the badge on would be the identity wrapper the composite tier
 * says not to add.
 *
 * @param props - {@link SummaryCardProps}
 */
export const SummaryCard = ({
    icon: Icon,
    value,
    label,
    hint,
    onPress,
    classNames,
}: SummaryCardProps) => {
    const rows = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between"
                items={[
                    () => <span className="text-accent-soft-foreground"><Icon /></span>,
                    () => <ChevronRightIcon className="size-5 text-muted" />,
                ]}
            />
        ),
        () => (
            <StackV
                gap={1}
                items={[
                    () => <Typography size="h4" weight="bold" text={value} />,
                    () => <Typography size="sm" weight="medium" text={label} />,
                    ...(hint ? [() => <Typography size="xs" color="muted" text={hint} />] : []),
                ]}
            />
        ),
    ]

    return (
        <PressableCard
            identity={{ tier: "block", component: "SummaryCard" }}
            onPress={onPress}
            className={cn(
                "card card--default h-full rounded-xl border border-divider/60 p-4 transition-colors",
                "hover:border-accent/40 hover:bg-accent/5",
                classNames,
            )}
        >
            <StackV gap={4} items={rows} />
        </PressableCard>
    )
}

"use client"

import React, { type ComponentType } from "react"
import Link from "next/link"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"
import { type VerdictBand, verdictBandClassName } from "../verdict-band"

/**
 * The interactive anchor for a clickable surface-list row. An INTERNAL app route
 * (href starting with `/`) renders a Next `<Link>` → client-side `router.push`:
 * SPA navigation that keeps history (Back works) with NO full-page reload — and
 * NEVER `router.replace` (a link click must not erase the entry it came from).
 * Protocol / external hrefs (`mailto:`, `tel:`, `http(s)://`, `#`) fall back to a
 * native `<a>` (Next `<Link>` is for in-app routes only). Ref feedback 2026-07-17
 * "clicking a row = router.push, not router.replace, even if it's a link".
 *
 * Shared by {@link SurfaceListCardRow} and {@link SurfaceListCardItem} — each hands
 * in its own `dataComponent` so the rendered anchor still carries that caller's own
 * identity rather than a generic one.
 */
/** Props for {@link RowAnchor}. */
interface RowAnchorProps {
    href: string
    onClick?: () => void
    className?: string
    dataComponent: string
    children: React.ReactNode
}

const RowAnchor = ({
    href,
    onClick,
    className,
    dataComponent,
    children,
}: RowAnchorProps) => {
    if (href.startsWith("/")) {
        return (
            <Link href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
                {children}
            </Link>
        )
    }
    return (
        <a href={href} onClick={onClick} className={className} data-tier="composite" data-component={dataComponent}>
            {children}
        </a>
    )
}

/** Props for {@link SurfaceListCard}. */
export interface SurfaceListCardProps extends WithClassNames<undefined> {
    /** The rows ({@link SurfaceListCardRow}) of the joined list. */
    children: React.ReactNode
    /**
     * Renders `border border-default` instead of `shadow-surface` — for when
     * this list sits NESTED inside another surface (a modal/drawer body),
     * where `--surface-shadow` can render invisible against the parent surface
     * (dark mode) — nested cards need a border to delineate (`components/card.md`
     * §"surface-in-surface / nested" — KEEP border, do NOT convert to shadow).
     * Defaults to `false` (existing top-level usages keep the shadow look).
     */
    bordered?: boolean
    /**
     * Set when a sentence-tier component roots on this card: it then emits THAT
     * component's identity instead of its own, so the caller never wraps itself in an
     * identity div (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * Bounded SURFACE list card: one `bg-surface` container with a border + large
 * radius, holding {@link SurfaceListCardRow}s edge-to-edge (the `Accordion
 * variant="surface"` skin — NOT a real accordion). Each row owns the FULL-BLEED
 * separator + hover; the last row hides its separator automatically (reviewer,
 * 2026-07-14: "surface-in-surface gets a full-width separator too") — full-bleed
 * everywhere, no inset-vs-nested split).
 *
 * Use for a list of clickable items that should read as ONE card (foundation
 * categories/resources, payment methods…), not N separate cards. Style lives
 * here (block); features only feed rows. Ref `elements/card.md` §3c.
 *
 * REUSE NOTE: `composites/cards/SurfaceCard`'s `.List` member is the newer,
 * DATA-driven (`items`) sibling of this exact shape (its own header even says
 * "was `SurfaceListCard` + its two rows"). This folder keeps the original
 * children-based API on purpose — ~90 call sites across the app compose it with
 * JSX rows today, and moving them to `items` is a call-site migration outside
 * this pass's scope, not a rewrite this file can make alone.
 *
 * @param props - {@link SurfaceListCardProps}
 * @see Story: .storybook/stories/blocks/cards/SurfaceListCard/SurfaceListCard.stories
 */
export const SurfaceListCard = ({ children, bordered = false, className, identity }: SurfaceListCardProps) => (
    <div
        className={cn(
            "overflow-hidden rounded-3xl bg-surface",
            bordered ? "border border-default" : "shadow-surface",
            className,
        )}
        {...resolveIdentity(identity, { tier: "composite", name: "SurfaceListCard" })}
    >
        {children}
    </div>
)

/** Props for {@link SurfaceListCardRow}. */
export interface SurfaceListCardRowProps extends WithClassNames<undefined> {
    /** Optional leading slot (thumbnail/icon), kept at intrinsic size — a buildable slot. */
    leading?: ComponentType
    /** Primary line — medium foreground, single-line truncate. */
    title: string
    /** Optional secondary line — muted, smaller, single-line truncate. */
    subtitle?: string
    /** Optional right-aligned metadata slot (chips/counts) before the trailing slot — a buildable slot. */
    meta?: ComponentType
    /** Optional far-right slot (caret / inline action) — a buildable slot. */
    trailing?: ComponentType
    /** Press handler → renders an interactive `<button>` row. */
    onPress?: () => void
    /** Link target → renders an `<a>` row that navigates on click. */
    href?: string
    /** Tints the row as the active selection. */
    selected?: boolean
    /** Disables the row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment. `"fill"` (default) tints the whole row (`bg-default`) — for
     * card-like rows / bounded objects. `"underline"` is link-style: the TITLE
     * underlines on hover with NO row fill — for a list whose title IS the link
     * (e.g. a most-read list). Ref `interactive-needs-hover` (row-as-link → underline
     * the label, don't colour the whole block).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict band: an inset colored PILL on the left marking this row with a signal
     * that comes from DATA (`card.md` §3i) — e.g. a keyword's popularity tier. See
     * {@link VerdictBand} (same shape as `SurfaceListCardItem.withVerdict`).
     */
    withVerdict?: VerdictBand
}

/**
 * One row of a {@link SurfaceListCard}, laying out leading · title+subtitle ·
 * meta+trailing (the same slot shape as `ListRow`, surface-card skin) with a
 * full-bleed inset separator auto-hidden on the last row. STATIC by default (a
 * plain `<div>`, NO hover/focus/cursor); pass `onPress`/`href` to make the whole
 * row a tappable `<button>`/`<a>` with `hover:bg-default` + focus ring. A static
 * row never fakes interactivity with a hover tint (`hover-style-matches-clickable-nature`).
 *
 * The row's OWN frame (separator, hover fill, focus ring, verdict band) is a shape
 * decision this composite owns directly (`cn`) — no frame carries an `after:`
 * pseudo-element separator or a data-driven inset shadow. The row's INTERIOR —
 * leading · title/subtitle · meta/trailing — is assembled from `Typography` inside
 * `Box`/`StackH` frames wherever a frame can express it exactly (title/subtitle
 * keeps a literal `gap-0` column, one step tighter than `Stack`'s narrowest `gap={1}`
 * step, so it stays a plain flex column).
 *
 * @param props - {@link SurfaceListCardRowProps}
 */
export const SurfaceListCardRow = ({
    leading: Leading,
    title,
    subtitle,
    meta: Meta,
    trailing: Trailing,
    onPress,
    href,
    selected = false,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
}: SurfaceListCardRowProps) => {
    // a row is only interactive when it actually does something; a STATIC row must
    // not fake interactivity with a hover tint / focus ring / button semantics
    // (`hover-style-matches-clickable-nature` — mirrors SurfaceListCardItem).
    const interactive = Boolean(onPress || href)
    const underlineHover = hover === "underline"
    const rowClassName = cn(
        "relative flex w-full items-center gap-3 p-3 text-left",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        // hover + focus + cursor ONLY when interactive. link-style rows form a hover
        // `group` (the title underlines) with no fill; card-style rows tint the row
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        interactive && (underlineHover ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        "disabled:cursor-not-allowed disabled:opacity-60",
        selected && "bg-accent-soft",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        className,
    )

    const content = (
        <>
            {Leading ? <div className="shrink-0"><Leading /></div> : null}
            {/* Deliberately NOT `StackV`: the closest step on the frame's gap scale is
                `gap={1}` (0.25rem) and this column needs a true `gap-0` — the two text
                lines are meant to sit with no seam between them (missing vocabulary: the
                frame has no zero step, see `_spacing.ts` `AllowedGap`). */}
            <div className="flex min-w-0 flex-col gap-0">
                <Typography size="sm" truncate underlineOnGroupHover={underlineHover} text={title} />
                {subtitle ? <Typography size="xs" color="muted" truncate text={subtitle} /> : null}
            </div>
            {Meta || Trailing ? (
                <Box principle="push-end" className="ml-auto shrink-0"
                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                    <StackH gap={2} items={[() => (Meta ? <Meta /> : null), () => (Trailing ? <Trailing /> : null)]} />
                </Box>
            ) : null}
        </>
    )

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={rowClassName} dataComponent="SurfaceListCardRow">
                {content}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={rowClassName}
                data-tier="composite"
                data-component="SurfaceListCardRow"
            >
                {content}
            </button>
        )
    }
    // static row (no onPress/href) — a plain div: no button semantics, no hover
    return (
        <div className={rowClassName} data-tier="composite" data-component="SurfaceListCardRow">
            {content}
        </div>
    )
}

/** Props for {@link SurfaceListCardItem}. */
export interface SurfaceListCardItemProps extends WithClassNames<undefined> {
    /** Arbitrary row content (the block owns padding + the inset separator). */
    children: React.ReactNode
    /** Press handler → renders an interactive `<button>` row (hover + focus ring). */
    onPress?: () => void
    /** Link target → renders an `<a>` row that navigates on click. */
    href?: string
    /** Disables the interactive row (dimmed, non-interactive). */
    isDisabled?: boolean
    /**
     * Hover treatment for an interactive row. `"fill"` (default) tints the whole
     * row (`bg-default`) — the accordion-skin hover, for SELECT/expand rows that
     * keep you on the surface (e.g. payment methods). `"underline"` makes the row a
     * hover `group` with NO fill — for a NAV row whose title is a link (navigates
     * away); the feature adds `group-hover:underline` to its title. Ref
     * `hover-style-matches-clickable-nature` (go-there → underline, stay-here → fill).
     */
    hover?: "fill" | "underline"
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this row with a signal that
     * comes from DATA (`card.md` §3i) — e.g. the league's promote/demote zone. See
     * {@link VerdictBand} (same shape as `SectionCard.withVerdict`).
     */
    withVerdict?: VerdictBand
    /**
     * Caller identity to wear on this item's root instead of its own — pass this
     * when a sentence-tier component roots on this item (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/**
 * One free-form row of a {@link SurfaceListCard} — bespoke content (not the fixed
 * leading/title/subtitle slots of {@link SurfaceListCardRow}). The block owns the
 * row padding + inset bottom separator (auto-hidden on the last row); the feature
 * lays out whatever it needs inside (e.g. a changelog entry, or a course row with a
 * progress bar). STATIC by default; pass `onPress`/`href` to make the WHOLE row a
 * tappable `<button>`/`<a>`. `hover="fill"` (default) tints the row (accordion skin);
 * `hover="underline"` is link-style (the row is a `group`, no fill — the feature
 * underlines its own title). Ref `elements/card.md` §3b/§3c.
 *
 * @param props - {@link SurfaceListCardItemProps}
 */
export const SurfaceListCardItem = ({
    children,
    onPress,
    href,
    isDisabled = false,
    hover = "fill",
    withVerdict,
    className,
    identity,
}: SurfaceListCardItemProps) => {
    const interactive = Boolean(onPress || href)
    const itemClassName = cn(
        "relative block w-full p-3 text-left",
        verdictBandClassName(withVerdict),
        // first/last row own the container's corner radius so the verdict box-shadow HOOKS the corner
        withVerdict?.enable && "first:rounded-t-3xl last:rounded-b-3xl",
        // full-bleed separator, hidden on the last row of the card
        "after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-['']",
        "last:after:hidden",
        interactive && "outline-none transition-colors focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
        // link-style rows form a hover `group` (the title underlines) with NO fill;
        // select/expand rows tint the whole row (accordion skin)
        interactive && (hover === "underline" ? "group" : "hover:bg-default"),
        interactive && !isDisabled && "cursor-pointer",
        isDisabled && "cursor-not-allowed opacity-60",
        className,
    )
    const identityAttrs = resolveIdentity(identity, { tier: "composite", name: "SurfaceListCardItem" })

    if (href) {
        return (
            <RowAnchor href={href} onClick={onPress} className={itemClassName} dataComponent="SurfaceListCardItem">
                {children}
            </RowAnchor>
        )
    }
    if (onPress) {
        return (
            <button
                type="button"
                onClick={onPress}
                disabled={isDisabled}
                className={itemClassName}
                {...identityAttrs}
            >
                {children}
            </button>
        )
    }
    return (
        <div className={itemClassName} {...identityAttrs}>
            {children}
        </div>
    )
}

"use client"

import React, { useCallback } from "react"
import { Button, Link, Typography } from "@heroui/react"
import { GraduationCapIcon, TrashIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { useCourseDisplayPrice } from "@/hooks/useCourseDisplayPrice"
import { pathConfig } from "@/resources/path"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"

/** Props for {@link CartLine}. */
export interface CartLineProps {
    /** The cart row to render. */
    item: CartItemEntity
    /**
     * This course's checkout-preview line (real charged vs list price, already
     * display-ready). Undefined while the preview loads or on error → the line
     * falls back to the entity-derived display price.
     */
    previewLine?: CoursesCheckoutPreviewLine
    /** Remove this course from the cart. */
    onRemove: (courseId: string) => void
    /** Disables the remove button while a cart write is in flight. */
    isMutating: boolean
}

/**
 * One shopping-cart line (a {@link SurfaceListCardItem}): the course cover
 * ({@link IconTile}), its title linking to the course page, the per-course price
 * ({@link PriceTag}) — the real charged vs list price from the checkout preview,
 * falling back to the entity display price while the preview loads — and a trash
 * button to remove it. List-item component: props-only; the parent
 * {@link import("..").CartView} owns the data + handlers.
 *
 * @param props - {@link CartLineProps}
 */
export const CartLine = ({ item, previewLine, onRemove, isMutating }: CartLineProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { priceVnd, originalVnd } = useCourseDisplayPrice(item.course)

    // prefer the preview (real charged + list, display-ready); fall back to the
    // entity-derived display price until the preview resolves / on error.
    const discounted = previewLine?.chargedVnd ?? priceVnd
    const original = previewLine?.listVnd ?? originalVnd

    const onView = useCallback(
        () => router.push(pathConfig().locale(locale).course(item.course.displayId).build()),
        [router, locale, item.course.displayId],
    )

    return (
        <SurfaceListCardItem identity={{ tier: "block", component: "CartLine" }}>
            <div className="flex items-center gap-3">
                <IconTile
                    size="sm"
                    tone="accent"
                    icon={<GraduationCapIcon />}
                    src={item.course.coverImageUrl}
                    alt={item.course.title}
                />
                <div className="flex min-w-0 flex-1 flex-col gap-1">
                    <Link onPress={onView} className="min-w-0 text-foreground no-underline hover:underline">
                        <Typography type="body-sm" weight="medium" truncate title={item.course.title}>
                            {item.course.title}
                        </Typography>
                    </Link>
                    <PriceTagInline discounted={discounted} original={original} />
                </div>
                {/* remove = `danger-soft` (soft red tint), same family as the
                    repeatable-delete / cart-remove ruling (button.md §4/§4b) — reads
                    destructive without shouting when repeated down the list. */}
                <Button
                    isIconOnly
                    variant="danger-soft"
                    aria-label={t("cart.remove")}
                    isDisabled={isMutating}
                    onPress={() => onRemove(item.courseId)}
                    className="shrink-0"
                >
                    <TrashIcon className="size-5" />
                </Button>
            </div>
        </SurfaceListCardItem>
    )
}

"use client"

import React from "react"
import {
