"use client"

import { SealCheckIcon } from "@phosphor-icons/react"
import React, { type ComponentType } from "react"
import {
    cn,
    Card,
    Skeleton,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import { type WithClassNames } from "@/modules/types/base/class-name"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Props for {@link TierCardBase} (shared shell for {@link TierCard} and {@link FreeTierCard}). */
export interface TierCardBaseProps extends WithClassNames<undefined> {
    /**
     * Tier level icon — a BUILDABLE slot (uncalled component), never a built element:
     * an element handed in is already rendered, so this shell cannot decide not to.
     */
    icon: ComponentType
    /** Tier display name — text, so it arrives as text. */
    title: string
    /** Optional adornment rendered after the title (e.g. the "popular" chip). */
    badge?: ComponentType
    /** Short tagline shown in a fixed `h-[2lh]` slot so cards align. */
    description?: string
    /** Price block — a buildable slot; the tiers lay their price out differently. */
    price: ComponentType
    /** Feature rows shown in the footer, each rendered with a seal-check icon. */
    features: string[]
    /** Whether this tier is the user's current plan. */
    isCurrent: boolean
    /** Call-to-action rendered in place of the "current plan" badge — a buildable slot. */
    cta: ComponentType
    /**
     * First load, nothing in hand → every content slot shimmers while the card keeps
     * its own boxes, so the grid does not jump on resolve. The resting shape lives
     * HERE, in the file that owns it: three hand-mirrored twins used to describe this
     * same card and could drift from it independently.
     */
    isSkeleton?: boolean
    /**
     * Caller identity to wear on this shell's root instead of its own — pass this
     * when a sentence-tier card roots on this base (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/** How many feature rows the resting card shows — the paid tiers all list two. */
const SKELETON_FEATURE_ROWS = 2

/**
 * Shared shell for an AI subscription tier card (paid or free).
 *
 * Presentational only: renders the icon+title row, fixed-height description,
 * price block, current-plan badge vs CTA, and the feature list footer.
 * Callers ({@link TierCard}, {@link FreeTierCard}) supply tier-specific
 * content (icon, price layout, CTA) and keep their own business logic.
 * @param props - shell content for one tier card
 */
export const TierCardBase = ({
    icon: Icon,
    title,
    badge: Badge,
    description,
    price: Price,
    features,
    isCurrent,
    cta: Cta,
    className,
    isSkeleton = false,
    identity,
}: TierCardBaseProps) => {
    const t = useTranslations()
    // resting rows stand in for whatever the caller would have listed
    const featureRows = isSkeleton
        ? Array.from({ length: SKELETON_FEATURE_ROWS }, (_row, index) => index)
        : features.map((_feature, index) => index)

    return (
        <Card
            className={cn("flex h-full flex-col", className)}
            {...resolveIdentity(identity, { tier: "composite", name: "TierCardBase" })}
        >
            <Card.Content className="flex flex-1 flex-col gap-3">
                {/* icon + tier name (+ optional badge) — tight pair */}
                <div className="flex items-center gap-2">
                    {isSkeleton
                        ? <Skeleton className="size-6 shrink-0 rounded-full" />
                        : <Icon />}
                    <Typography type="h5" weight="semibold">
                        {isSkeleton ? <Skeleton className="h-5 w-16 rounded" /> : title}
                    </Typography>
                    {isSkeleton || !Badge ? null : <Badge />}
                </div>
                {/* short tagline — fixed slot so cards align */}
                <div className="h-[2lh]">
                    <Typography type="body-sm" color="muted" className="line-clamp-3">
                        {isSkeleton ? <Skeleton className="h-4 w-3/4 rounded" /> : (description ?? "")}
                    </Typography>
                </div>
                <div className="flex flex-col gap-2">
                    {isSkeleton ? <Skeleton className="h-9 w-24 rounded" /> : <Price />}
                </div>
                {isSkeleton ? (
                    <Skeleton className="h-10 w-full rounded-3xl" />
                ) : isCurrent ? (
                    <div className="flex w-full items-center justify-center rounded-3xl bg-success-soft px-3 py-2">
                        <Typography type="body-sm" weight="medium" className="text-success-soft-foreground">
                            {t("aiSubscription.currentPlan")}
                        </Typography>
                    </div>
                ) : <Cta />}
            </Card.Content>
            <Card.Footer>
                {/* feature list — seal-check icon + muted text */}
                <div className="flex flex-col gap-2">
                    {featureRows.map((index) => (
                        <div key={index} className="flex items-center gap-2">
                            {isSkeleton
                                ? <Skeleton className="size-5 shrink-0 rounded" />
                                : (
                                    <SealCheckIcon
                                        aria-hidden
                                        className="size-5 shrink-0 text-muted"
                                    />
                                )}
                            <Typography type="body-sm" color="muted">
                                {isSkeleton
                                    ? <Skeleton className="h-4 w-40 max-w-full rounded" />
                                    : features[index]}
                            </Typography>
                        </div>
                    ))}
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    cn,
    Button,
    Chip,
    Spinner,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import { formatVnd } from "@/modules/utils/format-vnd"
import { formatUsd } from "@/modules/utils/format-usd"
import type { AiSubscriptionTier } from "@/modules/api/graphql/queries/types/ai-subscription-tiers"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { type WithClassNames } from "@/modules/types/base/class-name"
import { TierLevelIcon } from "@/components/svg/TierLevelIcon"
import { TierCardBase } from "@/components/blocks/commerce/TierCardBase"

/** Props for {@link TierCard} (list item — per-item tier data only). */
export interface TierCardProps extends WithClassNames<undefined> {
    /** Tier this card represents. */
    /** The tier this card sells. Absent only while {@link TierCardProps.isSkeleton}. */
    tier?: AiSubscriptionTier
    /** Whether this tier is the user's current plan. */
    isCurrent: boolean
    /** First load → the shell rests; the twin that used to mirror this card is gone. */
    isSkeleton?: boolean
}

/** Placeholder for the resting card's slots — the shell shimmers over every one of them. */
const EmptySlot = () => null

/**
 * One purchasable AI subscription tier card.
 *
 * List item: receives its own tier data + current flag; self-opens the shared
 * payment overlay for the buy action via {@link usePaymentOverlayState}.
 * Composes {@link TierCardBase} for the shared shell (surface color, no
 * shadow per global, `rounded-3xl`); the popular tier gets an accent border + ring.
 * @param props - tier, current state
 */
export const TierCard = ({
    tier,
    isCurrent,
    className,
    isSkeleton = false,
}: TierCardProps) => {
    const t = useTranslations()
    const { open: openPaymentModal } = usePaymentOverlayState()

    const onPress = useCallback(
        () => {
            if (!tier) {
                return
            }
            openPaymentModal({
                flow: PaymentFlow.AiSubscription,
                tier: tier.tier,
            })
        },
        [
            tier,
            openPaymentModal,
        ],
    )
    // Resting: the SHELL draws every box, so nothing here needs a tier yet. Returning
    // early is what lets the loaded branch below read `tier` without a guard on each line.
    if (isSkeleton || !tier) {
        return (
            <TierCardBase
                identity={{ tier: "block", component: "TierCard" }}
                isSkeleton
                className={className}
                icon={EmptySlot}
                title=""
                price={EmptySlot}
                features={[]}
                isCurrent={false}
                cta={EmptySlot}
            />
        )
    }

    // ascending tier level — Plus=2, Pro=3, Max=4 (highlighted bars)
    const tierLevel = tier.tier === "max"
        ? 4
        : tier.tier === "pro"
            ? 3
            : 2
    return (
        <TierCardBase
            identity={{ tier: "block", component: "TierCard" }}
            className={cn(
                tier.popular ? "border-accent ring-2 ring-accent/30" : "",
                className,
            )}
            icon={() => (
                <TierLevelIcon
                    level={tierLevel}
                    className="size-6 shrink-0 text-accent-soft-foreground"
                />
            )}
            title={tier.displayName}
            badge={tier.popular
                ? () => (
                    <Chip
                        size="sm"
                        color="accent"
                        variant="soft"
                    >
                        <Chip.Label>{t("aiSubscription.popular")}</Chip.Label>
                    </Chip>
                )
                : undefined}
            description={tier.description ?? ""}
            price={() => (
                <>
                    {/* VND number prominent + "/month" */}
                    <div className="flex flex-wrap items-baseline gap-x-2">
                        <Typography type="h3" weight="bold">
                            {formatVnd(tier.priceVnd)}
                        </Typography>
                        <Typography type="body-sm" color="muted">
                            {t("aiSubscription.perMonth")}
                        </Typography>
                    </div>
                    {/* secondary USD line — what international gateways charge */}
                    <div className="h-[3lh]">
                        <Typography type="body-sm" color="muted">
                            {t("aiSubscription.priceUsdHint", { amount: formatUsd(tier.priceUsd) })}
                        </Typography>
                    </div>
                </>
            )}
            features={[
                t("aiSubscription.creditsPer5h", { credits: tier.creditsPer5h }),
                t("aiSubscription.creditsPerWeek", { credits: tier.creditsPerWeek }),
            ]}
            isCurrent={isCurrent}
            cta={() => (
                <Button
                    variant="primary"
                    fullWidth
                    onPress={onPress}
                >
                    {({ isPending }) => (
                        <>
                            {isPending ? (
                                <Spinner
                                    color="current"
                                    size="sm"
                                />
                            ) : null}
                            {t("aiSubscription.buy")}
                        </>
                    )}
                </Button>
            )}
        />
    )
}

"use client"

import React from "react"
import {
    Link,
    Typography,
    cn,
} from "@heroui/react"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { VerdictBand } from "@/components/blocks/cards/verdict-band"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Box } from "@/components/frames/Box"
import {
    placeMedalIcon,
    rankBadgeIcon,
} from "@/components/blocks/dashboard/rankBadge"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One normalised leaderboard row (the container maps its query data into this). */
export interface LeaderboardRow {
    /** React key + stable id. */
    key: string
    /** 1-based rank — ≤3 renders a place medal, else the number. */
    rank: number
    /** Display username (null → dash). */
    username: string | null
    /** Avatar URL (null → generated fallback). */
    avatar?: string | null
    /** Pre-formatted trailing value (e.g. "640 pts" / "1420 XP"). */
    valueLabel: React.ReactNode
    /** True → highlight as the viewer (accent value + `meLabel` suffix). */
    isMe?: boolean
    /** Profile link target; omit → the identity is non-clickable. */
    profileHref?: string
    /** Context action at the far right (rank-delta caret / follow button). */
    trailing?: React.ReactNode
    /**
     * Optional left band (`SurfaceListCardItem.withVerdict`, `card.md` §3i) — a DATA
     * signal on this row (e.g. the weekly cohort's promote/demote zone). Pass the
     * canonical {@link VerdictBand} (`variant`/`color`) — NOT a free-form `className`,
     * which `verdictBandClassName` silently ignores (was the "invisible border" bug).
     */
    verdict?: VerdictBand
}

/** The viewer's own standing shown as the card's header line. */
export interface LeaderboardStanding {
    /** Viewer's rank — drives the leading {@link IconTile} badge (medal ≤3 / cup 4+). */
    rank: number
    /** Primary line (e.g. "Rank #1 · top 20%"). */
    primary: React.ReactNode
    /** Secondary muted line (e.g. "640 pts · Resets in 1 day 18 hours"). */
    secondary?: React.ReactNode
}

/** Props for {@link LeaderboardListCard}. */
export interface LeaderboardListCardProps extends WithClassNames<undefined> {
    /**
     * Bare mode — skip the {@link LabeledCard} frame (`title`/`onSeeMore` ignored) and
     * render just the standing + list. For a full page that already has its own
     * `PageHeader` (the course leaderboard); the dashboard cards leave it off.
     */
    bare?: boolean
    /** Card label (LabeledCard heading). Ignored when `bare`. */
    title?: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label. */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). */
    standing?: LeaderboardStanding
    /**
     * Optional node between the standing and the list — e.g. a `Podium` on a spacious
     * page (course leaderboard). Dashboard cards omit it (compact, no podium).
     */
    topSlot?: React.ReactNode
    /** The ranked rows (top-N slice; when a podium is in `topSlot`, pass rank 4+). */
    rows: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    /** "You" suffix appended to the viewer's own row name. */
    meLabel?: React.ReactNode
}

/**
 * The ONE shared render for a dashboard leaderboard preview — a {@link LabeledCard}
 * with the viewer's own standing (rank-driven {@link IconTile} badge: medal for the
 * podium, cup below) over a bordered {@link SurfaceListCard} of ranked rows (top-3
 * wear place medals). Both the weekly "Weekly league" and the global "Top learners"
 * cards map their data into this, so they render IDENTICALLY (teacher 2026-07-17 "2
 * identical sections"); only the per-context `trailing` slot (rank-delta caret vs follow)
 * and the emergent badge differ. Presentational + props-only; containers own the fetch.
 *
 * @param props - {@link LeaderboardListCardProps}
 */
export const LeaderboardListCard = ({
    bare = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    topSlot,
    rows,
    selfRow,
    ellipsisLabel,
    meLabel,
    className,
}: LeaderboardListCardProps) => {
    /** Render one row (shared by the ranked list and the pinned self-row). */
    const renderRow = (row: LeaderboardRow) => {
        const displayName = row.isMe && row.username && meLabel
            ? `${row.username} · ${meLabel}`
            : (row.username ?? "")
        const identity = (
            <UserCell
                username={displayName}
                avatar={row.avatar ?? undefined}
                isOwnRow={row.isMe }
            />
        )
        return (
            <SurfaceListCardItem key={row.key} withVerdict={row.verdict}>
                <div className="flex items-center gap-3">
                    {/* top-3 → place medal (🥇🥈🥉); rank 4+ → plain number. Number matches the
                        medal's w-6 CENTERED slot (teacher 2026-07-17 "4 and 5 still misaligned") at the same
                        text-sm foreground as the name (same-row same-size, `visual-hierarchy`). */}
                    {row.rank <= 3 ? (
                        <span className="flex w-6 shrink-0 items-center justify-center">
                            {placeMedalIcon(row.rank)}
                        </span>
                    ) : (
                        <span className="flex w-6 shrink-0 items-center justify-center text-sm text-foreground">
                            {row.rank}
                        </span>
                    )}
                    {row.profileHref ? (
                        <Link
                            href={row.profileHref}
                            className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                        >
                            {identity}
                        </Link>
                    ) : (
                        <div className="flex min-w-0 flex-1 items-center">{identity}</div>
                    )}
                    {/* value = meta → always muted + right-aligned tabular so the XP column
                        lines up across rows (teacher 2026-07-17: accent moves to the NAME, value
                        stays muted). */}
                    <Typography
                        type="body-sm"
                        color="muted"
                        className="shrink-0 text-right tabular-nums"
                    >
                        {row.valueLabel}
                    </Typography>
                    {row.trailing ? (
                        <div className="flex shrink-0 items-center">{row.trailing}</div>
                    ) : null}
                </div>
            </SurfaceListCardItem>
        )
    }

    const content = (
        <>
            {/* viewer's own standing — rank-driven badge (medal/cup) + rank text */}
            {standing ? (
                <div className="flex items-center gap-3">
                    <IconTile icon={rankBadgeIcon(standing.rank)} tone="neutral" size="sm" />
                    <div className="flex min-w-0 flex-col">
                        <Typography type="body-sm" weight="bold" truncate>
                            {standing.primary}
                        </Typography>
                        {standing.secondary ? (
                            <Typography type="body-xs" color="muted">
                                {standing.secondary}
                            </Typography>
                        ) : null}
                    </div>
                </div>
            ) : null}

            {/* optional podium (spacious page) between standing and the list */}
            {topSlot}

            {/* skip the list card entirely when there are no rows (all on the podium) */}
            {rows.length > 0 || selfRow ? (
                <SurfaceListCard bordered>
                    {rows.map(renderRow)}
                    {/* viewer below the slice → collapsed-rows ellipsis + pinned self-row.
                        Renders as a REAL row (teacher 2026-07-17): a `SurfaceListCardItem` so it
                        gets the same `p-3` + full-bleed separator, a transparent bg that INHERITS
                        the card's `bg-surface` (no `bg-surface-secondary` banner), and `min-h-8`
                        on the inner box to match the avatar rows' height exactly (avatar sm =
                        size-8). The ⋯ sits in the same `w-6` centred slot as the rank number so it
                        aligns as one of the rows, not a strip between them. */}
                    {selfRow ? (
                        <>
                            <SurfaceListCardItem>
                                <div className="flex min-h-8 items-center gap-3">
                                    <span className="flex w-6 shrink-0 items-center justify-center text-base leading-none tracking-widest text-muted">
                                        ⋯
                                    </span>
                                    <Typography type="body-sm" color="muted">
                                        {ellipsisLabel}
                                    </Typography>
                                </div>
                            </SurfaceListCardItem>
                            {renderRow(selfRow)}
                        </>
                    ) : null}
                </SurfaceListCard>
            ) : null}
        </>
    )

    // bare → the page owns the frame (PageHeader); dashboard cards keep the LabeledCard
    if (bare) {
        return (
            <Box
                identity={{ tier: "block", component: "LeaderboardListCard" }}
                className={cn("flex flex-col gap-3", className)}
            >
                {content}
            </Box>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "LeaderboardListCard" }}
            // `title` is only ever omitted in `bare` mode, which already returned above —
            // the fallback here is a type-safety guard, not a real state either caller hits.
            label={title ?? ""}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            className={className}
            contentClassName="flex flex-col gap-3"
        >
            {content}
        </LabeledCard>
    )
}

"use client"

import React, { useEffect, useRef } from "react"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import type { ComposerProps } from "@/components/blocks/feed/Composer"

/** One message rendered by {@link ChatPanel}. */
export interface ChatPanelMessage {
    /** Stable id — used as the React key. */
    id: string
    /** Author of the message — maps to the {@link ChatBubble} alignment + tint. */
    role: "user" | "assistant"
    /** Message body (text or a markdown render), rendered inside the bubble. */
    content: React.ReactNode
    /**
     * Optional tool-result row rendered below the bubble, assistant-aligned — e.g. a
     * {@link import("@/components/blocks/learn/ChatToolResult").ChatToolResult}. The
     * caller builds it; the panel only places it.
     */
    toolResult?: React.ReactNode
}

/**
 * Props for the {@link ChatPanel} block.
 *
 * A full chat surface: a scrollable message list, an optional typing indicator, an
 * empty-state slot, and a sticky-bottom {@link Composer}. Tier-3 presentational —
 * all data + the composer wiring arrive via props; the only side-effect is an
 * auto-scroll-to-bottom effect on the list ref.
 */
export interface ChatPanelProps extends WithClassNames<undefined> {
    /** The conversation, oldest first. Each entry renders one {@link ChatBubble}. */
    messages: Array<ChatPanelMessage>
    /** Props forwarded to the sticky-bottom {@link Composer} (controlled by the parent). */
    composer: ComposerProps
    /** When true, a three-dot typing indicator shows below the last message. */
    isTyping?: boolean
    /** Rendered centered in the list area when there are no messages. */
    emptyState?: React.ReactNode
}

/**
 * ChatPanel assembles the existing feed primitives into a complete chat surface:
 * a scrollable list of {@link ChatBubble}s (with optional tool-result rows
 * interleaved under assistant turns), an optional animated typing indicator, an
 * empty-state slot when the conversation is empty, and a sticky-bottom
 * {@link Composer} for the next message. The list auto-scrolls to the newest turn
 * whenever the messages or typing state change.
 *
 * Tier-3 presentational block: props-only, no store, no SWR. The parent owns the
 * message data and the composer's controlled draft.
 *
 * @param props - {@link ChatPanelProps}
 *
 * @example
 * <ChatPanel
 *   messages={turns}
 *   composer={{ value: draft, onChange: setDraft, onSubmit: send }}
 *   isTyping={isThinking}
 * />
 * @see Story: .storybook/stories/blocks/feed/ChatPanel/ChatPanel.stories
 */
export const ChatPanel = ({
    messages,
    composer,
    isTyping = false,
    emptyState,
    className,
}: ChatPanelProps) => {
    const listRef = useRef<HTMLDivElement>(null)

    // keep the newest turn in view as the conversation (or typing state) grows
    useEffect(() => {
        const element = listRef.current
        if (!element) {
            return
        }
        element.scrollTop = element.scrollHeight
    }, [messages, isTyping])

    const isEmpty = messages.length === 0

    return (
        <div
            className={cn(
                "flex flex-col overflow-hidden rounded-3xl border border-default bg-surface",
                "h-[32rem]",
                className,
            )}
        >
            {/* scrollable message list */}
            <div ref={listRef} className="flex-1 overflow-y-auto p-4">
                {isEmpty ? (
                    <div className="flex h-full items-center justify-center">
                        {emptyState}
                    </div>
                ) : (
                    <div className="flex flex-col gap-3">
                        {messages.map((message) => (
                            <div key={message.id} className="flex flex-col gap-2">
                                <ChatBubble role={message.role}>
                                    {message.content}
                                </ChatBubble>
                                {/* optional tool-result row, assistant-aligned under the bubble */}
                                {message.toolResult ? (
                                    <div className="flex justify-start">
                                        <div className="w-full max-w-[85%]">
                                            {message.toolResult}
                                        </div>
                                    </div>
                                ) : null}
                            </div>
                        ))}

                        {/* three-dot typing indicator on the assistant side */}
                        {isTyping ? (
                            <div className="flex justify-start">
                                <div className="flex items-center gap-1 rounded-2xl bg-surface-secondary px-3 py-3">
                                    {[0, 1, 2].map((dot) => (
                                        <span
                                            key={dot}
                                            className="size-1.5 animate-bounce rounded-full bg-muted"
                                            style={{ animationDelay: `${dot * 0.15}s` }}
                                        />
                                    ))}
                                </div>
                            </div>
                        ) : null}
                    </div>
                )}
            </div>

            {/* sticky-bottom composer */}
            <div className="border-t border-default p-3">
                <Composer {...composer} />
            </div>
        </div>
    )
}

"use client"

import React, { useEffect, useRef } from "react"
import { Button, Spinner, TextArea, TextField, cn } from "@heroui/react"
import { PaperPlaneRightIcon } from "@phosphor-icons/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/**
 * Props for the {@link Composer} block.
 *
 * A single message-input row: an optional leading avatar, an auto-growing text
 * field, and a trailing action cluster (an optional attach slot + a primary Send
 * button). CONTROLLED — the draft text lives in the parent; the block only mirrors
 * it, grows the field to fit, and fires callbacks. Tier-3 presentational: no store,
 * no fetch, no side-effects beyond a height-sync effect on the textarea ref.
 */
export interface ComposerProps extends WithClassNames<undefined> {
    /** The current draft text (controlled by the parent). */
    value: string
    /** Fired on every keystroke with the next draft text. */
    onChange: (value: string) => void
    /**
     * Fired when the viewer submits — via the Send button or Ctrl/Cmd+Enter. Only
     * fires when the trimmed value is non-empty and not already submitting.
     */
    onSubmit: () => void
    /** Placeholder shown while the field is empty. */
    placeholder?: string
    /**
     * Optional leading avatar image url. When set, a small {@link UserAvatar} sits
     * at the start of the row; omit to render the field flush to the edge.
     */
    avatarSrc?: string
    /**
     * While a submit is in flight: the Send button shows a spinner and is disabled,
     * and Ctrl/Cmd+Enter is ignored (blocks double-submit).
     */
    isSubmitting?: boolean
    /** Label for the primary Send button. Defaults to "Send". */
    submitLabel?: string
    /**
     * Optional slot placed BEFORE the Send button — e.g. an attach icon-button. The
     * owning feature supplies it so the block stays presentational.
     */
    attachSlot?: React.ReactNode
}

/**
 * Composer is a controlled message-input row: an optional leading avatar, an
 * auto-growing {@link TextArea} (HeroUI compound field, `variant="secondary"` —
 * the composer always sits on a surface), and a trailing action
 * cluster made of an optional attach slot plus a primary Send button. The Send
 * button is disabled whenever the trimmed draft is empty OR a submit is in flight;
 * Ctrl/Cmd+Enter submits under the same guard. The field grows with its content
 * (a height-sync effect on the textarea ref) instead of scrolling internally.
 *
 * Tier-3 presentational block: props-only, no store, no SWR. The parent owns the
 * draft text and decides what submit does.
 *
 * @param props - {@link ComposerProps}
 *
 * @example
 * <Composer
 *   value={draft}
 *   onChange={setDraft}
 *   onSubmit={send}
 *   avatarSrc={me.avatar}
 *   placeholder="Say something..."
 * />
 * @see Story: .storybook/stories/blocks/feed/Composer/Composer.stories
 */
export const Composer = ({
    value,
    onChange,
    onSubmit,
    placeholder,
    avatarSrc,
    isSubmitting = false,
    submitLabel = "Send",
    attachSlot,
    className,
}: ComposerProps) => {
    const textareaRef = useRef<HTMLTextAreaElement>(null)
    // only submit a non-empty draft that is not already in flight
    const canSubmit = value.trim().length > 0 && !isSubmitting

    // auto-grow: reset then match the field's height to its content on every change
    useEffect(() => {
        const element = textareaRef.current
        if (!element) {
            return
        }
        element.style.height = "auto"
        element.style.height = `${element.scrollHeight}px`
    }, [value])

    // Ctrl/Cmd+Enter submits (plain Enter keeps inserting newlines)
    const onKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
            event.preventDefault()
            if (canSubmit) {
                onSubmit()
            }
        }
    }

    return (
        <div className={cn("flex items-end gap-3", className)}>
            {/* optional leading avatar — omitted when no src is supplied */}
            {avatarSrc ? (
                <UserAvatar size="sm" avatar={avatarSrc} className="mb-1 shrink-0" />
            ) : null}

            {/* auto-growing field */}
            <TextField variant="secondary" className="min-w-0 flex-1">
                <TextArea
                    ref={textareaRef}
                    rows={1}
                    value={value}
                    onChange={(event) => onChange(event.target.value)}
                    onKeyDown={onKeyDown}
                    placeholder={placeholder}
                    className="max-h-40 resize-none"
                />
            </TextField>

            {/* trailing action cluster: optional attach slot, then the primary Send */}
            <div className="flex shrink-0 items-center gap-1">
                {attachSlot}
                <Button
                    size="sm"
                    variant="primary"
                    onPress={onSubmit}
                    isDisabled={!canSubmit}
                >
                    {isSubmitting ? (
                        <Spinner size="sm" color="current" />
                    ) : (
                        <PaperPlaneRightIcon aria-hidden focusable="false" className="size-4" />
                    )}
                    {submitLabel}
                </Button>
            </div>
        </div>
    )
}

import React from "react"
import type { ComponentType, ReactNode, SVGProps } from "react"
import { InfoIcon, LightbulbIcon, MapPinIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `SubmissionFindingsList` — "Feedback": one accordion row per quality-gate finding
 * on a graded attempt — severity icon + plain-text message (backtick code only) +
 * location chip in the trigger; markdown detail, a linked file location, and a
 * markdown suggestion in the panel. The frame is `SurfaceCard.Accordion` end to end;
 * the block supplies the domain (severity → icon/tone/sort-rank, the high→low sort,
 * the repo-URL → file-link builder). Loading, empty, error, and populated are all
 * states of the one accordion card, routed through its own `isSkeleton`/`emptyState`
 * axes.
 */

/** Severity a finding carries — drives the trigger icon/tone and the sort rank (high sorts first). */
export type SubmissionFeedbackSeverity = "high" | "medium" | "low"

/** An icon passed as a COMPONENT, rendered by this block at the size the text beside it uses. */
type SeverityIconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** One severity's trigger icon + text tone + sort rank — see {@link SEVERITY_VISUAL}. */
interface SeverityVisual {
    /** Trigger icon for this severity. */
    icon: SeverityIconComponent
    /** Tailwind text-color class for the icon (matches the severity's weight). */
    iconTone: string
    /** Sort rank — lower sorts first (high = 0). */
    rank: number
}

/**
 * Severity → trigger icon + text tone + sort rank. This is the block's own
 * domain vocabulary, never something a caller hands in.
 */
const SEVERITY_VISUAL: Record<SubmissionFeedbackSeverity, SeverityVisual> = {
    high: { icon: WarningCircleIcon, iconTone: "text-danger", rank: 0 },
    medium: { icon: WarningCircleIcon, iconTone: "text-warning", rank: 1 },
    low: { icon: InfoIcon, iconTone: "text-muted", rank: 2 },
}

/** One quality-gate finding for a graded attempt. */
export interface SubmissionFinding {
    /** Stable id — also the accordion row's expand key. */
    id: string
    /**
     * Short summary shown (clamped to one line) in the accordion trigger — plain
     * text, at most `` `code` `` spans (never bold/italic/link: a trigger title
     * is tier 1). Full markdown
     * belongs in `detail`/`suggestion`, which render in the panel body instead.
     */
    message: string
    /** Longer explanation, authored as markdown, shown in the panel. */
    detail?: string
    /** Suggested fix, authored as markdown, shown in the panel. */
    suggestion?: string
    /** Repo-relative file path this finding points at, e.g. `src/app/page.tsx`. */
    location?: string
    /** High/medium/low — decides the trigger icon/tone and the sort order. */
    severity: SubmissionFeedbackSeverity
    /** Author-authored order among findings that share a severity. Defaults to `0`. */
    sortIndex?: number
}

/** Props for {@link SubmissionFindingsList}. */
export interface SubmissionFindingsListProps {
    /** The findings, in ANY order — the block re-sorts them itself (severity, then `sortIndex`). */
    findings: Array<SubmissionFinding>
    /**
     * Repo URL the attempt was submitted from — turns each `location` into a
     * `blob/HEAD` deep-link. Omit → `location` still shows, as plain text.
     */
    repositoryUrl?: string
    /** Section label rendered above the card (e.g. `"Feedback"`). */
    label: string
    /** `true` → this list's own fetch is in flight; the card falls to its self-mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the card falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state title. Defaults to a standard "no findings yet" line. */
    emptyLabel?: string
    /** Truthy → the card falls to its error message (beats loading/empty — see file header). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No feedback yet"
const ERROR_TITLE = "Could not load feedback"

/**
 * High → low, then by each finding's own authored order. The block's own
 * vocabulary, so a caller never has to pre-sort what it hands in.
 */
const sortFindings = (findings: ReadonlyArray<SubmissionFinding>): Array<SubmissionFinding> =>
    [...findings].sort((a, b) => {
        const rankDiff = SEVERITY_VISUAL[a.severity].rank - SEVERITY_VISUAL[b.severity].rank
        return rankDiff !== 0 ? rankDiff : (a.sortIndex ?? 0) - (b.sortIndex ?? 0)
    })

/**
 * `repositoryUrl` + a repo-relative `location` → a `blob/HEAD` deep-link. Ported
 * from `FindingAccordionItem` unchanged.
 */
const buildLocationHref = (location: string, repositoryUrl?: string): string | undefined =>
    repositoryUrl ? `${repositoryUrl.replace(/\.git$/, "")}/blob/HEAD/${location.replace(/^\//, "")}` : undefined

/**
 * Trigger icon: the severity glyph, its OWN tone colour independent of the
 * title text — rides `titleStart`, not composed into `title` itself (§ same
 * rule as `ChallengeDeliverableList`'s status icon).
 */
const findingIcon = (finding: SubmissionFinding): ReactNode => {
    const { icon: Icon, iconTone } = SEVERITY_VISUAL[finding.severity]
    return (
        <Icon
            aria-hidden
            focusable="false"
            weight="bold"

            className={cn("size-3.5 shrink-0", iconTone)}
        />
    )
}

/** Trailing trigger slot: the finding's file location, as a quiet chip. */
const findingLocationChip = (finding: SubmissionFinding): ReactNode | undefined =>
    finding.location ? (
        <Chip
            tone="default"
            text={finding.location}
            classNames={["shrink-0"]}

        />
    ) : undefined

/**
 * Panel content: the markdown detail, the linked file location, and the markdown
 * suggested fix — each optional, each its own row (`related`: independent facts
 * about one finding, not a single unit of meaning).
 */
const findingPanel = (finding: SubmissionFinding, repositoryUrl: string | undefined): ReactNode => {
    const locationHref = finding.location ? buildLocationHref(finding.location, repositoryUrl) : undefined
    const locationRow = finding.location ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <MapPinIcon aria-hidden focusable="false" weight="bold" className="size-3 shrink-0 text-muted" />,
                () =>
                    locationHref ? (
                        <Typography
                            size="xs"
                            color="muted"
                            isLink
                            underlineOnHover
                            href={locationHref}
                            target="_blank"
                            rel="noopener noreferrer"
                            text={finding.location}

                        />
                    ) : (
                        <Typography size="xs" color="muted" text={finding.location} />
                    ),
            ]}
        />
    ) : null
    const suggestionRow = finding.suggestion ? (
        <StackH
            gap={2}
            align="start"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <LightbulbIcon aria-hidden focusable="false" weight="bold" className="size-3.5 shrink-0 text-muted" />,
                () => (
                    <div className="min-w-0 flex-1 text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.suggestion ?? ""}
                            measure="compact"

                        />
                    </div>
                ),
            ]}
        />
    ) : null
    return (
        <StackV
            gap={3}

            items={[
                ...(finding.detail ? [() => (
                    <div className="text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.detail ?? ""}
                            measure="compact"

                        />
                    </div>
                )] : []),
                () => locationRow,
                () => suggestionRow,
            ]}
        />
    )
}

/** Props for {@link ErrorEmptyState}. */
interface ErrorEmptyStateProps {
    onRetry?: () => void
    retryLabel?: string
}

const ErrorEmptyState = ({ onRetry, retryLabel }: ErrorEmptyStateProps) => (
    <AsyncContentError
        title={ERROR_TITLE}
        onRetry={onRetry}
        retryLabel={retryLabel}
    />
)

/** Props for {@link PlainEmptyState}. */
interface PlainEmptyStateProps {
    title: string
}

const PlainEmptyState = ({ title }: PlainEmptyStateProps) => (
    <AsyncContentEmpty title={title} />
)

/**
 * The "Feedback" findings card. See the file header for what this block owns
 * (severity vocabulary, sort order, the repo-URL→file-link builder) and why
 * loading/empty/error all stay bounded inside the one `SurfaceCard.Accordion`
 * frame instead of swapping it out for `AsyncContent`'s own switch.
 *
 * @param props - {@link SubmissionFindingsListProps}
 */
const SubmissionFindingsList = ({
    findings,
    repositoryUrl,
    label,
    isLoading = false,
    isEmpty,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionFindingsListProps) => {
    // Error outranks even a stale loading/skeleton flag — same priority order
    // `AsyncContent` itself documents ("error → loading → empty → content") — so a
    // caller handing both `error` and `isLoading` still sees the error, not a
    // skeleton pretending the fetch is still running.
    const skeleton = !error && (isLoading || isSkeleton)
    const resolvedEmpty = !error && (isEmpty ?? findings.length === 0)

    const items: Array<SurfaceCardAccordionItem> = error
        ? []
        : sortFindings(findings).map((finding) => ({
            id: finding.id,
            titleStart: () => findingIcon(finding),
            title: finding.message,
            titleEnd: () => findingLocationChip(finding),
            body: () => findingPanel(finding, repositoryUrl),
        }))

    const emptyState = error
        ? () => <ErrorEmptyState onRetry={onRetry} retryLabel={retryLabel} />
        : resolvedEmpty
            ? () => <PlainEmptyState title={emptyLabel ?? EMPTY_LABEL_DEFAULT} />
            : undefined

    return (
        <SurfaceCardAccordion
            identity={{ tier: "block", component: "SubmissionFindingsList" }}
            label={label}
            items={items}
            isSkeleton={skeleton}
            emptyState={emptyState}


        />
    )
}

export { SubmissionFindingsList }

"use client"

import React, { useMemo } from "react"
import { Pagination } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ChallengeCard } from "./ChallengeCard"
import { ChallengeCardSkeleton } from "./ChallengeCardSkeleton"
import _ from "lodash"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { WithClassNames } from "@/modules/types/base/class-name"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { UpNextCard } from "@/components/blocks/learn/UpNextCard"
import { useQueryChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryChallengesSwr"
import { setChallengePageNumber } from "@/redux/slices/challenge"
import { useLessonNavigation } from "../hooks/useLessonNavigation"

/** Props for {@link ChallengeBody}. */
export type ChallengeBodyProps = WithClassNames<undefined>

/** Content tab body listing the lesson's challenges, paginated. */
export const ChallengeBody = ({ className }: ChallengeBodyProps) => {
    const t = useTranslations()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const queryChallengesSwr = useQueryChallengesSwr()
    const challenges = useAppSelector((state) => state.challenge.entities)
    const count = useAppSelector((state) => state.challenge.count)
    // completion handoff: when the learner has PASSED every challenge of THIS lesson,
    // the natural next rung is the NEXT lesson (within the learn-content track).
    const completionTasks = useAppSelector((state) => state.challenge.completionTasks)
    const content = useAppSelector((state) => state.content.entity)
    const { next } = useLessonNavigation()
    const allChallengesPassed = useMemo(
        () => {
            const contentChallenges = content?.challenges ?? []
            return contentChallenges.length > 0
                && contentChallenges.every(
                    (challenge) => completionTasks.find((task) => task.id === challenge.id)?.completed === true,
                )
        },
        [content?.challenges, completionTasks],
    )
    const limit = useAppSelector((state) => state.challenge.limit)
    const pageNumber = useAppSelector((state) => state.challenge.pageNumber)
    // gate on first-load only (NOT isValidating) — a background revalidate on page
    // change keeps the current cards on screen instead of flashing the skeleton
    const isLoading = queryChallengesSwr.isLoading
    // surface fetch failures (e.g. the FE↔BE schema drift that broke this tab) as a
    // distinct error+retry state instead of an indistinguishable "no challenges" empty
    const error = queryChallengesSwr.error
    const isEmpty = !isLoading && !error && !challenges?.length
    const pageSize = limit ?? 10
    const totalPages = useMemo(() => {
        if (count == null || count <= 0) {
            return 0
        }
        return Math.max(1, Math.ceil(count / pageSize))
    }, [count, pageSize])
    const pageNumbers = useMemo(
        () => Array.from({ length: totalPages }, (_, index) => index + 1),
        [totalPages],
    )
    const currentPage = pageNumber ?? 1
    // frameless ONLY once real cards render (each ChallengeCard self-frames); while
    // loading/empty/erroring there is no bounded surface, so LabeledCard's own Card
    // must frame it — otherwise the section's label would also disappear along with
    // the frame (AsyncContent used to sit OUTSIDE LabeledCard entirely).
    const hasChallenges = !isLoading && !error && !isEmpty

    return (
        <LabeledCard
            identity={{ tier: "block", component: "ChallengeBody" }}
            label={t("challenge.count", { count: count ?? 0 })}
            frameless={hasChallenges}
            className={className}
        >
            <AsyncContent
                isLoading={isLoading}
                skeleton={(
                    <div className="flex flex-col gap-3">
                        <ChallengeCardSkeleton />
                        <ChallengeCardSkeleton />
                    </div>
                )}
                isEmpty={isEmpty}
                emptyContent={{ title: t("challenge.empty") }}
                error={error}
                errorContent={{
                    title: t("challenge.errorTitle"),
                    description: t("challenge.errorDescription"),
                    onRetry: () => queryChallengesSwr.mutate(),
                    retryLabel: t("challenge.retry"),
                }}
            >
                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-3">
                        {
                            _.cloneDeep(challenges)
                                ?.sort((prev, next) => prev.sortIndex - next.sortIndex)
                                .map((challenge) => <ChallengeCard key={challenge.id} challenge={challenge} />)
                        }
                    </div>
                    {count ? (
                        <Pagination
                            aria-label={t("common.pagination.navAria")}
                            className="justify-start"
                            size="sm"
                        >
                            <Pagination.Content className="flex flex-wrap justify-start gap-1">
                                <Pagination.Item>
                                    <Pagination.Previous
                                        aria-label={t("common.pagination.previous")}
                                        isDisabled={currentPage <= 1}
                                        onPress={() => dispatch(setChallengePageNumber(currentPage - 1))}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                    >
                                        <Pagination.PreviousIcon />
                                    </Pagination.Previous>
                                </Pagination.Item>
                                {pageNumbers.map((pageNumber) => (
                                    <Pagination.Item key={pageNumber}>
                                        <Pagination.Link
                                            isActive={pageNumber === currentPage}
                                            onPress={() => dispatch(setChallengePageNumber(pageNumber))}
                                            className="cursor-pointer rounded-medium transition-colors hover:bg-default data-[active=true]:hover:bg-accent"
                                        >
                                            {pageNumber}
                                        </Pagination.Link>
                                    </Pagination.Item>
                                ))}
                                <Pagination.Item>
                                    <Pagination.Next
                                        aria-label={t("common.pagination.next")}
                                        isDisabled={currentPage >= totalPages}
                                        onPress={() => dispatch(setChallengePageNumber(currentPage + 1))}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                    >
                                        <Pagination.NextIcon />
                                    </Pagination.Next>
                                </Pagination.Item>
                            </Pagination.Content>
                        </Pagination>
                    ) : null}
                    {/* passed every challenge of this lesson → hand off to the next lesson */}
                    {allChallengesPassed && next ? (
                        <UpNextCard
                            showCheck
                            eyebrow={t("content.upNext.challengesDoneEyebrow")}
                            title={t("content.upNext.nextLessonTitle", { title: next.title })}
                            description={t("content.upNext.nextLessonDesc")}
                            ctaLabel={t("content.upNext.nextLessonCta")}
                            onPress={() => router.push(next.href)}
                        />
                    ) : null}
                </div>
            </AsyncContent>
        </LabeledCard>
    )
}
